// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  course: CourseStore
  module: ModuleStore
  lesson: LessonStore
  enrollment: EnrollmentStore
  progress: ProgressStore
  liveSession: LiveSessionStore
  quizResult: QuizResultStore
  passwordResetToken: PasswordResetTokenStore

  constructor() {
    this.user = new UserStore()
    this.course = new CourseStore()
    this.module = new ModuleStore()
    this.lesson = new LessonStore()
    this.enrollment = new EnrollmentStore()
    this.progress = new ProgressStore()
    this.liveSession = new LiveSessionStore()
    this.quizResult = new QuizResultStore()
    this.passwordResetToken = new PasswordResetTokenStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.course.clear()
    this.module.clear()
    this.lesson.clear()
    this.enrollment.clear()
    this.progress.clear()
    this.liveSession.clear()
    this.quizResult.clear()
    this.passwordResetToken.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
